// Conecta BU -> correo al estudiante (RF-013).
// 1) Verifica que la peticion venga del backend (cabecera X-Conecta-BU-Secret).
// 2) Arma asunto y mensaje segun el tipo de automatizacion.
const secreto = $env.CONECTA_BU_SECRET || '';
const cabeceras = $json.headers || {};
if (secreto && cabeceras['x-conecta-bu-secret'] !== secreto) {
  throw new Error('Peticion rechazada: secreto invalido.');
}

const { tipo, datos = {} } = $json.body || {};
const estudiante = datos.estudiante;
if (!estudiante || !estudiante.email) {
  // evento.publicado no tiene destinatario individual: no se envia correo.
  return [];
}

const fecha = (iso) => iso
  ? new Date(iso).toLocaleDateString('es-CO', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'UTC' })
  : '';
const hora = (iso) => iso
  ? new Date(iso).toLocaleTimeString('es-CO', { hour: 'numeric', minute: '2-digit', timeZone: 'UTC' })
  : '';

const nombre = (estudiante.nombre || '').split(' ')[0] || 'estudiante';
const cita = datos.cita || {};
const evento = datos.evento || {};

const plantillas = {
  'cita.agendada': {
    asunto: 'Tu cita de orientación quedó agendada',
    cuerpo: `Tu cita de <b>${cita.servicio || 'orientación'}</b> quedó agendada para el <b>${fecha(cita.fecha)}</b> a las <b>${hora(cita.horaInicio)}</b>.<br>Si no puedes asistir, cancélala desde «Mis citas» con al menos 24 horas de anticipación.`,
  },
  'cita.cancelada': {
    asunto: 'Tu cita de orientación fue cancelada',
    cuerpo: `Tu cita de <b>${cita.servicio || 'orientación'}</b> del ${fecha(cita.fecha)} a las ${hora(cita.horaInicio)} fue cancelada. Puedes agendar una nueva cuando quieras.`,
  },
  'evento.inscripcion': {
    asunto: `Inscripción confirmada: ${evento.nombre || 'evento'}`,
    cuerpo: `Quedaste inscrito/a en <b>${evento.nombre || 'el evento'}</b>, el <b>${fecha(evento.fecha)}</b> a las <b>${hora(evento.horaInicio)}</b>${evento.lugar ? ' en ' + evento.lugar : ''}. ¡Te esperamos!`,
  },
  'evento.inscripcion_cancelada': {
    asunto: `Cancelaste tu inscripción: ${evento.nombre || 'evento'}`,
    cuerpo: `Cancelaste tu inscripción a <b>${evento.nombre || 'el evento'}</b>. Tu cupo quedó libre para otra persona.`,
  },
};

const plantilla = plantillas[tipo];
if (!plantilla) return [];

const html = `<div style="font-family:Arial,sans-serif;max-width:560px;color:#0E1726">
  <div style="background:#0B2A5B;color:#fff;padding:20px 24px;border-radius:12px 12px 0 0">
    <strong style="font-size:18px">Conecta BU</strong><br><span style="color:#E8B23A;font-size:13px">Bienestar Universitario · Uniautónoma del Cauca</span>
  </div>
  <div style="background:#FBF7EE;padding:24px;border-radius:0 0 12px 12px;line-height:1.6">
    <p>Hola, ${nombre}:</p><p>${plantilla.cuerpo}</p>
    <p style="font-size:12px;color:#5B6478">Este es un mensaje automático de Conecta BU. En una emergencia llama a la línea 123.</p>
  </div></div>`;

return [{ json: { para: estudiante.email, asunto: plantilla.asunto, html } }];
